// Public presentation layer. All fixtures below are fictional, not official announcements.
let language='zh',newsFilter='全部',searchTerm='',resourceTerm='',slide=0;
const posts=[
 {id:'reading',cat:'競賽公告',date:'2026.09.29',title:'英語朗讀競賽｜報名資訊與參賽須知',en:'English Reading Competition — Registration',body:'學校可在這裡了解競賽資訊，再由學校承辦人員登入辦理報名。',detail:'請先查看競賽頁的組別與參賽說明。正式競賽日期、地點、評分標準及報名期限，應以日後核定的競賽公告為準；此頁僅示範公告呈現方式。',facts:[['適合誰看','參賽學校的老師與承辦人員'],['如何報名','由學校承辦人員登入後填寫；訪客可先查閱競賽資訊'],['正式時程','待核定公告提供，請勿依示範日期安排']],links:[['查看競賽資訊','competition'],['學校登入入口','login']],files:['競賽報名準備清單（示範）','參賽須知摘要（示範）']},
 {id:'camp-news',cat:'營隊活動',date:'2026.09.28',title:'英語故事探索營｜場次資訊搶先看',en:'English Story Camp — Sessions',body:'英語故事探索營提供不同梯次，請先查看活動日期、適合年級與可報名名額。',detail:'民眾不須申請帳號即可在營隊頁選擇梯次並報名。正取與備取餘額依選定梯次顯示；本版資料與送出結果均為模擬。',facts:[['適合誰看','想了解活動的家長、老師與一般訪客'],['如何報名','前往營隊活動，選擇活動與梯次後填寫資料'],['名額資訊','請以各梯次頁面顯示的示範餘額為準']],links:[['查看營隊活動與梯次','camp'],['營隊報名常見問題','faq']],files:[]},
 {id:'picture-book',cat:'資源分享',date:'2026.09.26',title:'教學資源上架｜一起用繪本說故事',en:'New Teaching Resource — Storytelling',body:'提供繪本共讀的課堂引導與活動設計示例，協助老師規劃英語教學活動。',detail:'示範教材包含暖身提問、小組討論與課後延伸，可至教學資源頁查看。圖片為原創插畫，不是實際課堂照片或正式中心教材。',facts:[['適合誰看','尋找英語教學點子的老師'],['內容','繪本共讀與課堂活動設計示例']],links:[['瀏覽教學資源','resource']],files:['繪本共讀活動說明（示範）'],image:'learning.png'},
 {id:'sharing',cat:'中心消息',date:'2026.09.24',title:'英語教學成果交流｜看見學校的創意',en:'Sharing Creative English Teaching',body:'透過學校教學成果分享，交流不同課堂活動與學習經驗。',detail:'成果頁展示虛構的教學活動摘要。正式上線時，應由學校提供可公開的成果文字與照片；目前圖片為原創插畫。',facts:[['內容','教學成果交流示例'],['照片來源','原創插畫，非真實活動紀錄']],links:[['查看成果分享','gallery']],files:[],image:'learning.png'}
];
const resources=[{title:'繪本共讀活動設計',en:'Picture-book Reading Activities',tag:'教學活動',desc:'從封面預測、角色討論到故事接龍，安排一堂有互動的共讀課。'}, {title:'生活英語情境任務',en:'Everyday English Tasks',tag:'課堂教材',desc:'利用問候、自我介紹與生活情境，練習表達與同儕合作。'}, {title:'英語朗讀準備清單',en:'Reading-aloud Checklist',tag:'競賽資源',desc:'整理文本熟悉度、語句停頓與練習紀錄等準備方向。'}];
const t=(zh,en)=>language==='en'?en:zh;
function publicNav(){return [['home',t('首頁','Home')],['about',t('認識中心','About')],['news',t('最新消息','News')],['competition',t('競賽活動','Competitions')],['resource',t('教學資源','Resources')],['gallery',t('成果分享','Highlights')],['camp',t('營隊活動','Camps')],['services',t('更多服務','More')]];}
function publicHeader(){return `<header class="visitor-tools"><form id="site-search" role="search"><label class="sr-only" for="keyword">${t('搜尋公開網站','Search public content')}</label><input id="keyword" name="q" placeholder="${t('搜尋公告、教材、活動…','Search news, resources, activities…')}" value="${esc(searchTerm)}" maxlength="80"><button class="primary" type="submit">${t('搜尋','Search')}</button></form><div class="visitor-actions"><button id="language" aria-label="${t('切換英文示範介面','Switch to Chinese')}">${t('English','繁體中文')}</button><button data-page="login" class="primary">${t('學校／管理員登入','Staff sign-in')}</button></div></header><div class="hot-search"><span>熱門搜尋（示例）</span> <button data-hot="競賽">競賽</button> <button data-hot="繪本">繪本</button> <button data-hot="營隊">營隊</button></div>`;}
function publicFooter(){return `<footer class="public-footer"><div><h3>臺中市英語教育資源中心</h3><p>ENGLISH EDUCATION RESOURCE CENTER</p><p>地址、電話、電子郵件、上班時間：待中心提供正式資料</p></div><div><button data-page="faq">${t('常見問答','FAQ')}</button> <button data-page="downloads">${t('檔案下載','Downloads')}</button> <button data-page="links">${t('好站連結','Useful links')}</button><p>瀏覽人數（靜態示例）：當前 12 · 本日 86 · 本月 320 · 本年 1,280</p><p>前端模擬原型 · 目前未取得無障礙標章 · 非正式營運網站</p></div></footer>`;}
function publicTitle(en,zh,desc){return heading(en,t(zh,en),desc);}
function newsRows(list){return list.map(n=>`<a class="news-row" href="#news/${n.id}"><time>${n.date}</time><span class="category">${n.cat}</span><strong>${esc(language==='en'?n.en:n.title)}</strong><span aria-hidden="true">＋</span></a>`).join('');}
function newsDetail(n){
 const facts=n.facts.map(([label,value])=>`<div><dt>${esc(label)}</dt><dd>${esc(value)}</dd></div>`).join('');
 const links=n.links.map(([label,target])=>`<a class="news-related-link" href="#${esc(target)}">${esc(label)} <span aria-hidden="true">→</span></a>`).join('');
 const files=n.files.length?`<section class="news-detail-section"><h2>相關檔案</h2><ul class="news-file-list">${n.files.map(name=>`<li><button data-download="${esc(name)}">${esc(name)}（TXT）</button><small>可下載的示範文字檔，非正式公版</small></li>`).join('')}</ul></section>`:'';
 const image=n.image?`<figure class="news-figure"><img src="${esc(n.image)}" alt="原創共讀插畫，非真實活動照片"><figcaption>原創插畫示意，非活動紀錄</figcaption></figure>`:'';
 return `<div class="news-detail"><div class="news-detail-actions"><button data-page="news">← 返回最新消息</button><button id="news-copy" type="button">複製這則消息的網址</button></div><article class="card news-article"><p class="news-meta"><span class="category">${esc(n.cat)}</span><time datetime="${n.date.replaceAll('.','-')}">公告日期：${esc(n.date)}</time><span>示範公告</span></p><h1>${esc(language==='en'?n.en:n.title)}</h1><p class="news-lead">${esc(n.body)}</p><section class="news-detail-section"><h2>閱讀重點</h2><dl class="news-facts">${facts}</dl></section><section class="news-detail-section"><h2>公告內容</h2><p>${esc(n.detail)}</p></section>${image}<section class="news-detail-section"><h2>相關連結</h2><div class="news-related">${links}</div></section>${files}</article></div>`;
}
function publicHome(){const banners=[{tag:'COMPETITION · 英語競賽',title:t('勇敢開口，<br>讓世界聽見你的聲音。','Speak with confidence.<br>Let your voice shine.'),desc:t('英語朗讀競賽資訊已上線。查看參賽須知，由學校統一辦理報名。','Explore our reading competition. Registration is handled by schools.'),label:t('查看競賽資訊','View competition'),page:'competition'}, {tag:'RESOURCES · 教學資源',title:t('一本繪本，<br>打開無限想像。','A storybook.<br>A world of possibilities.'),desc:t('探索英語共讀與生活情境教材，為下一堂課找到靈感。','Discover reading activities and ideas for your next lesson.'),label:t('瀏覽教學資源','Explore resources'),page:'resource'}];const b=banners[slide];return `<section class="hero public-hero" aria-label="${t('焦點活動輪播','Featured content')}"><div><div class="eyebrow">${b.tag}</div><h1>${b.title}</h1><p class="muted">${b.desc}</p><button data-page="${b.page}">${b.label}</button><div class="banner-controls">${banners.map((_,i)=>`<button data-slide="${i}" aria-pressed="${slide===i}" aria-label="${t('顯示第','Show slide ')}${i+1}${t('則焦點','')}" class="${slide===i?'selected':''}">${String(i+1).padStart(2,'0')}</button>`).join('')}<span>${t('活動及內容均為示例','Sample activities and content')}</span></div></div><div class="hero-art"><img src="learning.png" alt="老師與孩子共讀的原創插畫，非活動紀錄照片"></div></section><div class="quick-links"><button data-page="competition"><span class="quick-symbol">Aa</span><strong>${t('競賽活動','Competitions')}</strong><small>${t('參賽資訊與公告','Information & announcements')}</small></button><button data-page="resource"><span class="quick-symbol">ABC</span><strong>${t('教學資源','Resources')}</strong><small>${t('尋找下一堂課的靈感','Ideas for your classroom')}</small></button><button data-page="camp"><span class="quick-symbol">Hi!</span><strong>${t('營隊活動','Camps')}</strong><small>${t('查看場次與報名資訊','Sessions & registration')}</small></button><button data-page="results"><span class="quick-symbol">★</span><strong>${t('競賽結果','Results')}</strong><small>${t('出場序與得獎公告','Order & awards')}</small></button></div><section><div class="section-head"><div><div class="eyebrow">LATEST NEWS</div><h2>${t('中心最新消息','Latest news')}</h2></div><button data-page="news">${t('所有消息','All news')}</button></div><div class="news-panel">${newsRows(posts)}</div></section><section><div class="section-head"><div><div class="eyebrow">TEACH & SHARE</div><h2>${t('精選教學資源','Featured resources')}</h2></div><button data-page="resource">${t('所有資源','All resources')}</button></div><div class="grid">${resourceCards()}</div></section><div class="two" style="margin-top:30px"><section class="card"><div class="eyebrow">CAMP ACTIVITIES</div><h2>${t('英語故事探索營','English Story Camp')}</h2><p>${t('一起讀故事、用英語交流，探索學習的樂趣。','Read stories and discover the joy of learning together.')}</p><span class="badge green">${t('半日・一日・多日｜查看各梯次名額','Half-day, day and multi-day sessions')}</span><div class="actions"><button data-page="camp">${t('查看營隊場次','View sessions')}</button></div></section><section class="card"><div class="eyebrow">OUR CENTER</div><h2>${t('連結學校，分享教學的可能','Connecting schools and ideas')}</h2><p>${t('認識中心成員與工作職掌，尋找英語教育的交流資源。','Meet our team and explore teaching expertise.')}</p><div class="actions"><button data-page="about">${t('認識中心','About us')}</button><button data-page="talent">${t('人才資料庫','Expertise directory')}</button></div></section></div>`;}
function resourceCards(){return resources.map((r,i)=>`<a class="resource-card" href="#resource/${i}"><div class="resource-cover cover-${i}"><span>${['READ','HELLO','SPEAK'][i]}</span><small>${r.tag}</small></div><div><span class="badge">${r.tag}</span><h3>${esc(language==='en'?r.en:r.title)}</h3><p>${esc(r.desc)}</p><small>示範教材 · 非正式發布</small></div></a>`).join('');}
function content(a){if(role!=='visitor')return coreContent(a);
 if(page==='home')return publicHome();
 if(page==='news')return publicTitle('News','最新消息',t('競賽、營隊、資源與中心公告。以下日期與內容皆為示例。','Sample announcements and dates.'))+`<div class="tabs">${['全部','競賽公告','營隊活動','資源分享','中心消息'].map(c=>`<button data-filter="${c}" class="${newsFilter===c?'active':''}">${c}</button>`).join('')}</div><div class="news-panel">${newsRows(posts.filter(n=>newsFilter==='全部'||n.cat===newsFilter))}</div>`;
 if(page.startsWith('news/')){const n=posts.find(n=>n.id===page.slice(5));return n?newsDetail(n):notFound();}
 if(page==='resource')return publicTitle('Teaching Resources','教學資源',t('依關鍵字尋找教材與活動設計。','Find teaching ideas by keyword.'))+`<form id="resource-search" class="inline-search"><label for="resource-key">${t('教材關鍵字','Keyword')}</label><input id="resource-key" value="${esc(resourceTerm)}" maxlength="80"><button type="submit">${t('篩選教材','Filter')}</button></form><div class="grid">${resources.some(r=>[r.title,r.en,r.desc,r.tag].join(' ').toLowerCase().includes(resourceTerm.toLowerCase()))?resourceCardsFiltered():`<p role="status">查無符合教材，請試試「繪本」或清空關鍵字。</p>`}</div>`;
 if(page.startsWith('resource/')){const r=resources[Number(page.slice(9))];return r?publicTitle('Resource',r.title,'示範教材內容')+`<article class="card article"><span class="badge">${r.tag}</span><h2>${esc(language==='en'?r.en:r.title)}</h2><p>${r.desc}</p><h3>活動安排</h3><ol><li>以簡單提問引起學習動機。</li><li>分組討論並練習口語表達。</li><li>分享小組成果，進行回饋。</li></ol><p>內容為虛構教材，提供操作示範。</p><button data-download="${esc(r.title)}" class="primary">下載示範教材說明（TXT）</button></article>`:notFound();}
 if(page==='search'){const q=searchTerm.toLowerCase();const items=searchIndex().filter(r=>(r.title+' '+r.desc).toLowerCase().includes(q));return publicTitle('Search','全站搜尋',`關鍵字：${searchTerm||'（未輸入）'} · 搜尋範圍為本版公開示範內容`)+(!q?'<div class="card">請輸入關鍵字。</div>':`<div class="news-panel">${items.length?items.map(r=>`<a class="search-result" href="#${r.page}"><span class="badge">${r.kind}</span><h2>${esc(r.title)}</h2><p>${esc(r.desc)}</p></a>`).join(''):'<div class="empty"><h2>找不到符合的內容</h2><p>試試「競賽」、「繪本」或「營隊」。</p></div>'}</div>`);}
 if(page==='login')return publicTitle('Staff Sign-in','學校／管理員登入','本版不收集帳號、密碼，也未串接教育局 Open ID。')+`<div class="grid"><section class="card"><h2>一般學校</h2><p>正式登入方式：教育局 Open ID。進入報名、調查填報與資源上傳工作區。</p>${button('模擬學校登入','school','primary')}</section><section class="card"><h2>承辦學校</h2><p>以學校身分登入，由管理員開通承辦權限；保留一般學校功能。</p>${button('模擬承辦登入','host','primary')}</section><section class="card"><h2>系統管理員</h2><p>依需求書使用教育局 Open ID 或指定帳密；管理員授權不由本校身分自動推定。</p><button id="admin-login" class="primary">模擬管理員登入</button></section></div><div class="note" style="margin-top:20px">營隊活動開放民眾免登入報名；不提供學生帳號或單字練習。</div>`;
 if(page==='about')return publicTitle('About the Center','認識中心','中心資訊與成員公開欄位展示。')+`<div class="two"><section class="card"><h2>臺中市英語教育資源中心</h2><p>此頁示範中心介紹、工作組織圖與成員資訊的呈現方式。正式介紹文字與組織圖圖片待中心提供。</p><div class="org-placeholder">工作組織圖圖片<br><small>待提供正式素材，未自行編造組織關係</small></div></section><section class="card"><h2>中心聯絡資訊</h2><dl><dt>地址</dt><dd>待提供正式資料</dd><dt>電話／電子郵件</dt><dd>待提供正式資料</dd><dt>上班時間</dt><dd>待提供正式資料</dd></dl></section></div><div class="section-head"><h2>中心成員（虛構示例）</h2></div><div class="grid">${['行政聯繫','教學資源','活動協作'].map((x,i)=>`<div class="card"><span class="number">${i+1}</span><h3>示範成員 ${String.fromCharCode(65+i)}</h3><p>工作職掌：${x}<br>聯絡方式：未公開<br>照片：待提供</p></div>`).join('')}</div>`;
 if(page==='talent')return publicTitle('Expertise Directory','人才資料庫','僅呈現管理員允許公開的欄位；以下人員均為虛構。')+`<div class="grid">${[['國教輔導團','英語課程規劃'],['專家教師','繪本教學'],['教授學者','語言教育'],['領航員｜語文領域','課堂活動設計']].map((x,i)=>`<section class="card"><span class="badge">${x[0]}</span><h2>示範人員 ${i+1}</h2><p>服務單位：示範教育單位<br>專長領域：${x[1]}</p><small>電話、電子郵件與年資未公開</small></section>`).join('')}</div>`;
 if(page==='gallery')return publicTitle('School Highlights','成果分享','學校教學活動成果摘要。下方為原創插畫示意，非真實活動照片。')+`<div class="two"><article class="card"><img class="gallery-image" src="learning.png" alt="師生共讀原創插畫，非真實成果照片"><h2>英語繪本共讀日</h2><span class="badge">示範國小 · 閱讀活動</span><p>以故事討論及角色分享，鼓勵學生表達想法、一起享受閱讀。</p></article><section class="card"><h2>生活英語情境分享</h2><p>示範學校將問候與自我介紹融入課堂，透過小組任務增加口語互動。</p><span class="badge">成果文字示例 · 照片待提供</span></section></div>`;
 if(page==='camp')return publicTitle('Camp Activities','營隊活動','免申請帳號即可報名；本版僅展示場次與名額，不送出真實報名。')+`<div class="grid">${[['上午場','正取餘額 8','尚有名額'],['下午場','正取已滿 · 備取餘額 3','開放備取'],['週末場','正取及備取皆滿','已額滿不開放報名']].map((r,i)=>`<section class="card"><span class="badge ${i===2?'orange':'green'}">${r[2]}</span><h2>英語故事探索營 · ${r[0]}</h2><p>活動日期：依正式公告<br>報名期間：示範開放時段<br>${r[1]}（靜態示例）</p><button data-camp="${i}">查看場次與注意事項</button></section>`).join('')}</div><div id="camp-info" aria-live="polite"></div>`;
 if(page==='downloads')return publicTitle('Downloads','檔案下載','以下為可實際下載的示範文字檔，不是教育局正式公版文件。')+`<section class="card">${['競賽報名準備清單','教學資源上傳說明','中心服務項目說明'].map(x=>`<div class="download-row"><div><strong>${x}</strong><small>範例文件 · TXT · 2026.09.29</small></div><button data-download="${x}">下載示範檔</button></div>`).join('')}</section>`;
 if(page==='faq')return publicTitle('Frequently Asked Questions','常見問答','依需求書整理的使用方式；正式作業仍依各活動公告。')+`<div class="card faq">${[['學校如何登入？','一般學校與承辦學校使用教育局 Open ID；本版僅提供模擬登入。'],['承辦學校還可以參賽嗎？','可保留一般學校身分與功能，承辦權限由系統管理員設定。'],['營隊報名需要學生帳號嗎？','不用申請帳號密碼；正式系統須檢核重複報名與剩餘正備取名額。'],['收到補件通知後怎麼做？','學校登入查看審核意見，重新上傳後案件回到待審查。'],['是否提供線上單字練習？','需求書沒有這項功能，本專題不製作。']].map(([q,a])=>`<details><summary>${q}</summary><p>${a}</p></details>`).join('')}</div>`;
 if(page==='links')return publicTitle('Useful Links','好站連結','外部網站需連線。本版未預設任何未核定的推薦連結。')+'<section class="card"><h2>待中心提供推薦網站</h2><p>正式系統由管理員新增圖片或網址，點選後於新分頁開啟。風格參考網站不等同中心推薦連結。</p></section>';
 if(page==='public-plan')return publicTitle('Public Project Information','計畫公開資訊','依管理員公開設定呈現，與學校填報工作區分開。')+'<section class="card"><h2>英語閱讀推廣計畫（示例）</h2><p>公開欄位：計畫名稱、活動摘要。未公開欄位與附件不出現在此頁。</p><p>摘要：以繪本共讀與教學交流推廣英語閱讀。</p><span class="badge">公開設定示意，非實際審查結果</span></section>';
 if(page==='services')return publicTitle('More Services','更多服務','瀏覽中心資訊與公開文件。')+`<div class="grid">${[['talent','人才資料庫','尋找教學專長與交流資源'],['downloads','檔案下載','查看服務說明與活動文件'],['faq','常見問答','快速了解登入與報名方式'],['links','好站連結','中心推薦的外部網站'],['public-plan','計畫公開資訊','查看允許公開的計畫資料'],['about','聯絡中心','中心成員與聯絡資訊']].map(([id,title,desc])=>`<button class="card link" data-page="${id}"><h2>${title}</h2><p>${desc}</p></button>`).join('')}</div>`;
 return coreContent(a);
}
function notFound(){return '<section class="card"><h1>找不到這筆內容</h1><button data-page="home">回首頁</button></section>';}
function resourceCardsFiltered(){const parser=document.createElement('div');parser.innerHTML=resourceCards();return [...parser.children].filter((el,i)=>[resources[i].title,resources[i].en,resources[i].desc,resources[i].tag].join(' ').toLowerCase().includes(resourceTerm.toLowerCase())).map(el=>el.outerHTML).join('');}
function searchIndex(){return [...posts.map(n=>({title:n.title,desc:n.en+' '+n.cat+' '+n.body+' '+n.detail,page:'news/'+n.id,kind:'公告'})),...resources.map((r,i)=>({title:r.title,desc:r.en+' '+r.desc,page:'resource/'+i,kind:'教材'})),...['about','talent','gallery','camp','downloads','faq','links','public-plan'].map((id,i)=>({page:id,title:['中心介紹與聯絡資訊','人才資料庫','學校成果分享','英語故事探索營','檔案下載','常見問答','好站連結','計畫公開資訊'][i],desc:['成員 職掌 地址 電話','專家 教師 教授 領航員','繪本 教學 成果','營隊 場次 正取 備取','競賽 清單 資源 說明','Open ID 登入 報名 補件','推薦 網址','經費 計畫 摘要'][i],kind:'公開頁面'}))];}
function bindPublic(){document.querySelectorAll('[data-hot]').forEach(b=>b.onclick=()=>{searchTerm=b.dataset.hot;navigate('search');});document.querySelector('#site-search')?.addEventListener('submit',e=>{e.preventDefault();searchTerm=new FormData(e.target).get('q').trim();navigate('search');});document.querySelector('#resource-search')?.addEventListener('submit',e=>{e.preventDefault();resourceTerm=document.querySelector('#resource-key').value.trim();render();});document.querySelector('#language')?.addEventListener('click',()=>{language=language==='zh'?'en':'zh';render();});document.querySelector('#admin-login')?.addEventListener('click',()=>{role='admin';navigate('admin');});document.querySelectorAll('[data-slide]').forEach(b=>b.onclick=()=>{slide=Number(b.dataset.slide);render();});document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{newsFilter=b.dataset.filter;render();});document.querySelectorAll('[data-download]').forEach(b=>b.onclick=()=>{const title=b.dataset.download;const blob=new Blob(['\uFEFF'+title+'\n\n此為英語教育資源中心前端原型示範文件，不是正式公版。\n請依核定活動公告準備資料。'],{type:'text/plain;charset=utf-8'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=title+'_示範.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);});document.querySelector('#news-copy')?.addEventListener('click',async()=>{try{await navigator.clipboard.writeText(location.href);notify('已複製這則消息的網址');}catch{notify('請從瀏覽器網址列複製此頁連結');}});document.querySelectorAll('[data-camp]').forEach(b=>b.onclick=()=>{document.querySelector('#camp-info').innerHTML=`<section class="card" style="margin-top:20px"><h2>場次注意事項</h2><p>活動時間、適用年級、地點與報名資料欄位，依核定公告設定。這裡不收集真實個資。</p><p>${b.dataset.camp==='2'?'本場次已額滿，不能報名。':'正式系統將在送出時檢核重複報名、期間與名額。'}</p><span class="badge">本次未實作營隊表單送出</span></section>`;});}
function routeHash(){const hash=decodeURIComponent(location.hash.slice(1));if(hash.startsWith('news/')||hash.startsWith('resource/')||publicNav().some(x=>x[0]===hash)||['talent','downloads','faq','links','about','public-plan'].includes(hash)){role='visitor';page=hash;render();window.scrollTo(0,0);}}
window.addEventListener('hashchange',routeHash);render();if(location.hash)routeHash();
